def magic_square_test(matrix):
    n = len(matrix)
    total = n * (n ** 2 + 1) // 2

    # Check rows
    for row in matrix:
        if sum(row) != total:
            return False

    # Check columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != total:
            return False

    # Check diagonals
    if sum(matrix[i][i] for i in range(n)) != total:
        return False
    if sum(matrix[i][n - 1 - i] for i in range(n)) != total:
        return False

