def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Compute left increasing sums
    left = [0] * n
    left[0] = arr[0]
    for i in range(1, n):
        if arr[i] > arr[i-1]:
            left[i] = left[i-1] + arr[i]
        else:
            left[i] = arr[i]

    # Compute right decreasing sums
    right = [0] * n
    right[-1] = arr[-1]
    for i in range(n-2, -1, -1):
        if arr[i] > arr[i+1]:
            right[i] = right[i+1] + arr[i]
        else:
            right[i] = arr[i]

    # Find the maximum sum
    max_sum = 0
    for i in range(n):
        current_sum = left[i] + right[i] - arr[i]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

